items.solution:
function loadConfig(env, requiredKeys) {
  const config = {};
  for (const key of requiredKeys) {
    const value = env[key];
    if (!value) {
      throw new Error(`Missing required environment variable: ${key}`);
    }
    config[key] = value;
  }
  return config;
}

