  // for length <= 4, return all stars instead
}

items.solution:
function maskPartial(secretValue) {
  if (secretValue.length <= 4) return '*'.repeat(secretValue.length);
  const first = secretValue.slice(0, 2);
  const last = secretValue.slice(-2);
  const middle = '*'.repeat(secretValue.length - 4);
  return first + middle + last;
}

