function rotationStatus(daysSinceLastRotation, maxAgeDays) {
  if (daysSinceLastRotation >= maxAgeDays) return 'overdue';
  if (daysSinceLastRotation >= maxAgeDays - 7) return 'due-soon';
  return 'ok';
}
